import { useEffect, useMemo, useState } from "react";
import HomePage, { AssetItem } from "./pages/HomePage";
import BroadcastPage from "./pages/BroadcastPage";

type PageKey = "assets" | "broadcast" | "settings";
type SystemTone = "ok" | "busy" | "warn" | "off";

const navItems: Array<{
  key: PageKey;
  label: string;
  hint: string;
  icon: string;
}> = [
  {
    key: "assets",
    label: "我的素材",
    hint: "上传与整理",
    icon: "✦",
  },
  {
    key: "broadcast",
    label: "开播",
    hint: "预览与输出",
    icon: "●",
  },
  {
    key: "settings",
    label: "设置",
    hint: "账号与画面",
    icon: "⌁",
  },
];

const defaultAssets: AssetItem[] = [
  {
    id: "demo-1",
    name: "夏季上新主画面.jpg",
    type: "image",
    size: 1824000,
    createdAt: Date.now() - 1000 * 60 * 12,
    status: "ready",
    progress: 100,
    previewUrl:
      "data:image/svg+xml;utf8," +
      encodeURIComponent(`
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1200">
          <defs>
            <linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stop-color="#261d12"/>
              <stop offset="55%" stop-color="#0f0d09"/>
              <stop offset="100%" stop-color="#6f4f17"/>
            </linearGradient>
          </defs>
          <rect width="900" height="1200" fill="url(#g)"/>
          <circle cx="450" cy="435" r="210" fill="#d9b24c" opacity=".18"/>
          <rect x="170" y="600" width="560" height="250" rx="42" fill="#f2d982" opacity=".18"/>
          <text x="450" y="945" text-anchor="middle" font-size="48" fill="#f8eec3" font-family="Arial">LIVE MATERIAL</text>
        </svg>
      `),
    note: "已生成直播版本",
    variants: 6,
    risk: "low",
  },
  {
    id: "demo-2",
    name: "产品细节短视频.mp4",
    type: "video",
    size: 9340000,
    createdAt: Date.now() - 1000 * 60 * 28,
    status: "ready",
    progress: 100,
    previewUrl:
      "data:image/svg+xml;utf8," +
      encodeURIComponent(`
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1200">
          <rect width="900" height="1200" fill="#090806"/>
          <rect x="95" y="105" width="710" height="990" rx="76" fill="#17120a"/>
          <path d="M380 465 L575 600 L380 735 Z" fill="#f0c64f"/>
          <text x="450" y="930" text-anchor="middle" font-size="42" fill="#fff4c9" font-family="Arial">VIDEO READY</text>
        </svg>
      `),
    note: "可用于循环开播",
    variants: 4,
    risk: "low",
  },
];

function App() {
  const [page, setPage] = useState<PageKey>("assets");
  const [assets, setAssets] = useState<AssetItem[]>(defaultAssets);
  const [isLive, setIsLive] = useState(false);
  const [systemTone, setSystemTone] = useState<SystemTone>("ok");
  const [systemText, setSystemText] = useState("系统就绪");

  const readyCount = useMemo(
    () => assets.filter((item) => item.status === "ready").length,
    [assets]
  );

  const processingCount = useMemo(
    () =>
      assets.filter((item) =>
        ["uploading", "deduping", "checking", "making"].includes(item.status)
      ).length,
    [assets]
  );

  useEffect(() => {
    if (isLive) {
      setSystemTone("busy");
      setSystemText("正在开播");
      return;
    }

    if (processingCount > 0) {
      setSystemTone("busy");
      setSystemText("正在整理素材");
      return;
    }

    const hasReview = assets.some((item) => item.status === "review");
    if (hasReview) {
      setSystemTone("warn");
      setSystemText("有素材待确认");
      return;
    }

    if (readyCount > 0) {
      setSystemTone("ok");
      setSystemText("可开播");
      return;
    }

    setSystemTone("off");
    setSystemText("等待上传素材");
  }, [assets, isLive, processingCount, readyCount]);

  const renderPage = () => {
    if (page === "assets") {
      return (
        <HomePage
          assets={assets}
          setAssets={setAssets}
          onGoBroadcast={() => setPage("broadcast")}
        />
      );
    }

    if (page === "broadcast") {
      return (
        <BroadcastPage
          assets={assets}
          isLive={isLive}
          setIsLive={setIsLive}
          onNeedAssets={() => setPage("assets")}
        />
      );
    }

    return <SettingsLite />;
  };

  return (
    <div className="phs-app">
      <style>{globalStyles}</style>

      <aside className="phs-sidebar">
        <div className="brand-block">
          <div className="brand-mark">P</div>
          <div>
            <div className="brand-title">PHS</div>
            <div className="brand-subtitle">无人直播素材中控</div>
          </div>
        </div>

        <nav className="side-nav">
          {navItems.map((item) => (
            <button
              key={item.key}
              type="button"
              className={`side-nav-item ${page === item.key ? "active" : ""}`}
              onClick={() => setPage(item.key)}
            >
              <span className="side-nav-icon">{item.icon}</span>
              <span className="side-nav-copy">
                <strong>{item.label}</strong>
                <small>{item.hint}</small>
              </span>
            </button>
          ))}
        </nav>

        <div className="sidebar-spacer" />

        <div className={`system-pill ${systemTone}`}>
          <span className="status-dot" />
          <span>{systemText}</span>
        </div>
      </aside>

      <main className="phs-main">
        <header className="topbar">
          <div>
            <p className="eyebrow">PHS v1.1</p>
            <h1>
              {page === "assets"
                ? "我的素材"
                : page === "broadcast"
                ? "开播"
                : "设置"}
            </h1>
          </div>

          <div className="topbar-actions">
            <div className="soft-counter">
              <span>{readyCount}</span>
              <small>可用素材</small>
            </div>
            <button
              type="button"
              className="gold-button small"
              onClick={() => setPage("broadcast")}
              disabled={readyCount === 0}
            >
              去开播
            </button>
          </div>
        </header>

        {renderPage()}
      </main>
    </div>
  );
}

function SettingsLite() {
