import {
  Dispatch,
  DragEvent,
  SetStateAction,
  useMemo,
  useRef,
  useState,
} from "react";

export type AssetStatus =
  | "uploading"
  | "deduping"
  | "checking"
  | "making"
  | "ready"
  | "review"
  | "duplicate"
  | "failed";

export type AssetRisk = "low" | "medium" | "high";

export type AssetItem = {
  id: string;
  name: string;
  type: "image" | "video" | "file";
  size: number;
  createdAt: number;
  status: AssetStatus;
  progress: number;
  previewUrl?: string;
  note: string;
  variants: number;
  risk: AssetRisk;
  fingerprint?: string;
};

type HomePageProps = {
  assets: AssetItem[];
  setAssets: Dispatch<SetStateAction<AssetItem[]>>;
  onGoBroadcast: () => void;
};

const statusCopy: Record<AssetStatus, string> = {
  uploading: "上传中",
  deduping: "整理重复素材",
  checking: "检查画面",
  making: "生成直播版本",
  ready: "可开播",
  review: "待确认",
  duplicate: "已重复",
  failed: "处理失败",
};

const statusHint: Record<AssetStatus, string> = {
  uploading: "正在接收文件",
  deduping: "自动避免重复内容",
  checking: "检查水印和画面风险",
  making: "正在生成多种直播画面",
  ready: "已加入可开播素材池",
  review: "建议确认后再使用",
  duplicate: "已发现相同素材",
  failed: "请重新上传",
};

function HomePage({ assets, setAssets, onGoBroadcast }: HomePageProps) {
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(
    assets[0]?.id ?? null
  );
  const [filter, setFilter] = useState<"all" | "ready" | "processing" | "review">(
    "all"
  );

  const selectedAsset = useMemo(() => {
    if (!assets.length) return null;
    return assets.find((item) => item.id === selectedId) ?? assets[0];
  }, [assets, selectedId]);

  const readyCount = assets.filter((item) => item.status === "ready").length;
  const processingCount = assets.filter((item) =>
    ["uploading", "deduping", "checking", "making"].includes(item.status)
  ).length;
  const reviewCount = assets.filter((item) => item.status === "review").length;

  const visibleAssets = useMemo(() => {
    if (filter === "ready") {
      return assets.filter((item) => item.status === "ready");
    }

    if (filter === "processing") {
      return assets.filter((item) =>
        ["uploading", "deduping", "checking", "making"].includes(item.status)
      );
    }

    if (filter === "review") {
      return assets.filter((item) => item.status === "review");
    }

    return assets;
  }, [assets, filter]);

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFiles = (files: FileList | File[]) => {
    const fileArray = Array.from(files);
    if (!fileArray.length) return;

    const newAssets: AssetItem[] = fileArray.map((file) => {
      const type = file.type.startsWith("image/")
        ? "image"
        : file.type.startsWith("video/")
        ? "video"
        : "file";

      const fingerprint = `${file.name}_${file.size}_${file.lastModified}`;
      const alreadyExists = assets.some(
        (item) =>
          item.fingerprint === fingerprint ||
          `${item.name}_${item.size}` === `${file.name}_${file.size}`
      );

      const maybeHasWatermark =
        /watermark|logo|平台|抖音|快手|小红书|水印/i.test(file.name);

      return {
        id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
        name: file.name,
        type,
        size: file.size,
        createdAt: Date.now(),
        status: alreadyExists ? "duplicate" : "uploading",
        progress: alreadyExists ? 100 : 8,
        previewUrl: type === "image" || type === "video" ? URL.createObjectURL(file) : undefined,
        note: alreadyExists
          ? "系统已发现相同素材"
          : "正在上传并整理素材",
        variants: 0,
        risk: maybeHasWatermark ? "medium" : "low",
        fingerprint,
      };
    });

    setAssets((prev) => [...newAssets, ...prev]);
    setSelectedId(newAssets[0]?.id ?? selectedId);

    newAssets.forEach((item) => {
      if (item.status !== "duplicate") {
        simulateProcessing(item.id, item.risk);
      }
    });
  };

  const simulateProcessing = (id: string, risk: AssetRisk) => {
    const steps: Array<{
      delay: number;
      status: AssetStatus;
      progress: number;
      note: string;
      variants?: number;
    }> = [
      {
        delay: 350,
        status: "deduping",
        progress: 24,
        note: "正在整理重复素材",
      },
      {
        delay: 1100,
        status: "checking",
        progress: 52,
        note: "正在检查画面和水印风险",
      },
      {
        delay: 1900,
        status: "making",
        progress: 78,
        note: "正在生成直播版本",
        variants: 2,
      },
      {
        delay: 3000,
        status: risk === "medium" ? "review" : "ready",
        progress: 100,
        note: risk === "medium" ? "疑似含有水印，请确认" : "已生成直播版本",
        variants: risk === "medium" ? 2 : 6,
      },
    ];

    steps.forEach((step) => {
      window.setTimeout(() => {
        setAssets((prev) =>
          prev.map((item) =>
            item.id === id
              ? {
                  ...item,
                  status: step.status,
                  progress: step.progress,
                  note: step.note,
                  variants: step.variants ?? item.variants,
                }
              : item
          )
        );
      }, step.delay);
    });
  };

  const onDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragging(false);
    handleFiles(event.dataTransfer.files);
  };

  const markReady = (id: string) => {
    setAssets((prev) =>
      prev.map((item) =>
        item.id === id
          ? {
              ...item,
              status: "ready",
              risk: "low",
              note: "已人工确认，可用于开播",
              progress: 100,
            }
          : item
      )
    );
  };

  const removeAsset = (id: string) => {
    setAssets((prev) => prev.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  return (
    <section className="home-page page-enter">
      <style>{homeStyles}</style>

      <div className="home-hero">
        <div className="home-copy">
          <p className="eyebrow">上传素材，系统自动整理</p>
          <h2>把素材丢进来，PHS 会帮你变成可连续开播的内容。</h2>
          <p>
            自动去重、检查水印、生成不同画面版本。你只需要确认素材结果，然后去开播。
          </p>

          <div className="hero-actions">
            <button className="gold-button" type="button" onClick={handleUploadClick}>
              上传素材
            </button>
            <button
              className="ghost-button"
              type="button"
              onClick={onGoBroadcast}
              disabled={readyCount === 0}
            >
              用 {readyCount} 个素材开播
            </button>
          </div>
        </div>

        <div
