function formatSize(size: number) {
  if (size < 1024 * 1024) {
    return `${Math.max(1, Math.round(size / 1024))} KB`;
  }

  return `${(size / 1024 / 1024).toFixed(1)} MB`;
}

function riskText(risk: AssetRisk) {
  if (risk === "low") return "低";
  if (risk === "medium") return "中";
  return "高";
}

