import { useEffect, useMemo, useState } from "react";
import type { AssetItem } from "./HomePage";

type BroadcastPageProps = {
  assets: AssetItem[];
  isLive: boolean;
  setIsLive: (value: boolean) => void;
  onNeedAssets: () => void;
};

type StartState = "idle" | "warming" | "live" | "ending";

function BroadcastPage({
  assets,
  isLive,
  setIsLive,
  onNeedAssets,
}: BroadcastPageProps) {
  const readyAssets = useMemo(
    () => assets.filter((item) => item.status === "ready"),
    [assets]
  );

  const [startState, setStartState] = useState<StartState>(
    isLive ? "live" : "idle"
  );
  const [activeIndex, setActiveIndex] = useState(0);
  const [liveSeconds, setLiveSeconds] = useState(0);

  const activeAsset = readyAssets[activeIndex % Math.max(readyAssets.length, 1)];

  useEffect(() => {
    if (!isLive) {
      setLiveSeconds(0);
      return;
    }

    const timer = window.setInterval(() => {
      setLiveSeconds((value) => value + 1);
    }, 1000);

    return () => window.clearInterval(timer);
  }, [isLive]);

  useEffect(() => {
    if (!isLive || readyAssets.length <= 1) return;

    const timer = window.setInterval(() => {
      setActiveIndex((index) => (index + 1) % readyAssets.length);
    }, 4200);

    return () => window.clearInterval(timer);
  }, [isLive, readyAssets.length]);

  const handleStart = async () => {
    if (readyAssets.length === 0) {
      onNeedAssets();
      return;
    }

    setStartState("warming");

