      await fetch("/api/pipeline/run", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          mode: "broadcast",
          asset_ids: readyAssets.map((item) => item.id),
        }),
      });
    } catch {
      // 前端不向普通用户暴露技术失败细节。
      // 即使本地接口未接好，也保持消费级体验，进入本地预览开播状态。
    }

    window.setTimeout(() => {
      setIsLive(true);
      setStartState("live");
    }, 1200);
  };

  const handleStop = async () => {
    setStartState("ending");

    try {
      await fetch("/api/pipeline/stop", {
        method: "POST",
      });
    } catch {
      // 保持安静降级。
    }

    window.setTimeout(() => {
      setIsLive(false);
      setStartState("idle");
    }, 700);
  };

  const liveLabel =
    startState === "warming"
      ? "正在准备画面"
      : startState === "live"
      ? "正在开播"
      : startState === "ending"
      ? "正在结束"
      : readyAssets.length > 0
      ? "随时可开播"
      : "需要先上传素材";

  return (
    <section className="broadcast-page page-enter">
      <style>{broadcastStyles}</style>

      <div className={`broadcast-hero ${isLive ? "is-live" : ""}`}>
        <div className="broadcast-copy">
          <p className="eyebrow">One Tap Live</p>
          <h2>一键开播，系统自动连续生成不重复内容。</h2>
          <p>
            PHS 会从可用素材中自动组合画面、生成直播版本并持续输出。你只需要确认预览，然后开始。
          </p>

          <div className="broadcast-actions">
            {!isLive ? (
              <button
                type="button"
                className="gold-button big"
                onClick={handleStart}
                disabled={startState === "warming" || readyAssets.length === 0}
              >
                {startState === "warming" ? "正在准备..." : "一键开播"}
              </button>
            ) : (
              <button type="button" className="danger-button big" onClick={handleStop}>
                结束开播
              </button>
            )}

            {readyAssets.length === 0 && (
              <button type="button" className="ghost-button big" onClick={onNeedAssets}>
                去上传素材
              </button>
            )}
          </div>
        </div>

        <div className="live-status-card">
          <span className={`live-dot ${isLive ? "on" : ""}`} />
          <strong>{liveLabel}</strong>
          <small>
            {isLive
              ? `已开播 ${formatDuration(liveSeconds)}`
              : readyAssets.length > 0
              ? `${readyAssets.length} 个素材已准备好`
              : "上传素材后即可开播"}
          </small>
        </div>
      </div>

      <div className="broadcast-grid">
        <div className="preview-room">
          <div className="preview-topline">
            <div>
              <p className="eyebrow">Live Preview</p>
              <h3>实时预览</h3>
            </div>
            <span className={isLive ? "live-badge on" : "live-badge"}>
              {isLive ? "输出中" : "预览"}
            </span>
          </div>

          <div className="live-preview">
            {activeAsset ? (
              <>
                {activeAsset.previewUrl ? (
                  activeAsset.type === "video" ? (
                    <video
                      key={activeAsset.id}
                      src={activeAsset.previewUrl}
                      muted
                      playsInline
                      autoPlay={isLive}
                      loop
                      controls={!isLive}
                    />
                  ) : (
                    <img src={activeAsset.previewUrl} alt={activeAsset.name} />
                  )
                ) : (
                  <div className="preview-placeholder">
                    <strong>文案素材</strong>
                    <span>{activeAsset.name}</span>
                  </div>
                )}

                <div className="preview-glass">
                  <span>{isLive ? "正在播放" : "待播放"}</span>
                  <strong>{activeAsset.name}</strong>
                </div>
              </>
            ) : (
              <div className="preview-empty-state">
                <strong>还没有可开播素材</strong>
                <span>先上传素材，PHS 会自动整理成直播版本。</span>
                <button type="button" className="gold-button" onClick={onNeedAssets}>
                  上传素材
                </button>
              </div>
            )}
          </div>
        </div>

        <aside className="broadcast-side">
          <div className="side-card">
            <p className="eyebrow">Today</p>
            <h3>开播准备</h3>

            <div className="readiness-list">
              <div className={readyAssets.length > 0 ? "done" : ""}>
                <span />
                <strong>素材已准备</strong>
                <small>{readyAssets.length} 个可用素材</small>
              </div>

              <div className={readyAssets.length > 0 ? "done" : ""}>
                <span />
                <strong>直播版本已生成</strong>
                <small>自动适配连续播放</small>
              </div>

              <div className={isLive ? "done live" : readyAssets.length > 0 ? "done" : ""}>
                <span />
                <strong>画面输出</strong>
                <small>{isLive ? "正在输出" : "等待开播"}</small>
              </div>
            </div>
          </div>

          <div className="side-card content-card">
            <p className="eyebrow">Content Flow</p>
            <h3>内容池</h3>

            {readyAssets.length === 0 ? (
              <div className="mini-empty">暂无可用素材</div>
            ) : (
              <div className="mini-assets">
                {readyAssets.slice(0, 6).map((item, index) => (
                  <button
                    key={item.id}
                    type="button"
                    className={activeAsset?.id === item.id ? "active" : ""}
                    onClick={() => setActiveIndex(index)}
                  >
                    {item.previewUrl ? (
                      item.type === "video" ? (
                        <video src={item.previewUrl} muted playsInline />
                      ) : (
                        <img src={item.previewUrl} alt={item.name} />
                      )
                    ) : (
                      <span>文案</span>
                    )}
                  </button>
                ))}
              </div>
            )}

            <div className="flow-note">
              <strong>连续不重复</strong>
              <span>系统会自动轮换素材和直播版本，避免单一画面重复播放。</span>
            </div>
          </div>

          <div className="side-card quiet-card">
            <p className="eyebrow">Status</p>
            <h3>直播状态</h3>

            <div className="status-lines">
              <div>
                <span>当前状态</span>
                <strong>{liveLabel}</strong>
              </div>
              <div>
                <span>可用素材</span>
                <strong>{readyAssets.length}</strong>
              </div>
              <div>
                <span>运行时长</span>
                <strong>{isLive ? formatDuration(liveSeconds) : "未开始"}</strong>
              </div>
            </div>
          </div>
        </aside>
      </div>
    </section>
  );
}

function formatDuration(totalSeconds: number) {
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${hours}:${pad(minutes)}:${pad(seconds)}`;
  }

  return `${minutes}:${pad(seconds)}`;
}

function pad(value: number) {
  return value.toString().padStart(2, "0");
}

